import{_ as t,o as a,c as s,a6 as r}from"./chunks/framework.DIp0zHSV.js";const p=JSON.parse('{"title":"Internals","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/internals/index.md","filePath":"architecture/internals/index.md","lastUpdated":1794274588000}'),n={name:"architecture/internals/index.md"};function o(i,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="internals" tabindex="-1">Internals <a class="header-anchor" href="#internals" aria-label="Permalink to &quot;Internals&quot;">​</a></h1><p>This section documents lower-level implementation details under the <a href="./../subsystems/">core subsystems</a> and the <a href="./../cards/lcards-card-foundation.html">card foundation</a>. You rarely need to touch this code directly, but it helps when debugging unexpected rendering, contributing a new visual effect, or tracing data through the pipeline.</p><hr><h2 id="pages-in-this-section" tabindex="-1">Pages in This Section <a class="header-anchor" href="#pages-in-this-section" aria-label="Permalink to &quot;Pages in This Section&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="#background-animation-system">Background Animation System</a></td><td>Canvas2D and WebGL (three.js) rendering of animated card backgrounds</td></tr><tr><td><a href="#datasource-buffer-structure">DataSource Buffers</a></td><td>Internal buffer and processor-output data shape</td></tr><tr><td><a href="#home-assistant-entity-display-utility">Home Assistant Entity Display</a></td><td>Locale-aware entity value formatting</td></tr><tr><td><a href="#home-assistant-services-implementation-notes">Home Assistant Services: Implementation Notes</a></td><td>Backend action architecture and the server-push channel</td></tr><tr><td><a href="#shape-texture-system">Shape Texture System</a></td><td>Canvas2D textures and effects clipped inside button and elbow shapes</td></tr><tr><td><a href="#persistent-storage">Persistent Storage</a></td><td>The integration&#39;s key/value store: global, per-user and per-device settings</td></tr></tbody></table><hr><h2 id="background-animation-system" tabindex="-1">Background Animation System <a class="header-anchor" href="#background-animation-system" aria-label="Permalink to &quot;Background Animation System&quot;">​</a></h2><p><a href="./background-animation-system.html">Full reference →</a></p><p>How the <code>background_animation</code> layer of buttons, elbows, MSD and astrometrics cards is drawn: one <code>&lt;canvas&gt;</code> and one Canvas2D loop per card, preset effects stacked in config order, optional zoom layers, and a WebGL (three.js) version for many presets, drawn on one WebGL context shared by the page with the Canvas2D version as the fallback. On slow devices <code>AnimationPerformanceMonitor</code> makes the renderer skip frames, then stop it with a recovery probe.</p><p>Consult this when implementing a new background effect, configuring background animations on cards, or investigating performance degradation.</p><hr><h2 id="datasource-buffer-structure" tabindex="-1">DataSource Buffer Structure <a class="header-anchor" href="#datasource-buffer-structure" aria-label="Permalink to &quot;DataSource Buffer Structure&quot;">​</a></h2><p><a href="./datasource-buffers.html">Full reference →</a></p><p>Documents the internal shape of datasource data objects: the main <code>v</code> buffer holding raw entity values, and named processor buffers holding outputs from unit conversion, moving averages, rate calculations, and other pipeline stages.</p><p>Consult this when referencing datasource values in templates (<code>{ds:source.buffer}</code>), configuring processors, or accessing buffers directly via <code>DataSourceManager</code>.</p><hr><h2 id="home-assistant-entity-display-utility" tabindex="-1">Home Assistant Entity Display Utility <a class="header-anchor" href="#home-assistant-entity-display-utility" aria-label="Permalink to &quot;Home Assistant Entity Display Utility&quot;">​</a></h2><p><a href="./ha-entity-display.html">Full reference →</a></p><p>Centralised utility (<code>src/utils/ha-entity-display.js</code>) for locale-aware formatting of Home Assistant entity values. Delegates to the stable <code>hass.format*</code> API family and provides fallbacks. This is the single source of truth for Home Assistant text formatting in LCARdS; cards use the <code>LCARdSCard</code> wrappers (<code>_getStateDisplay()</code> and friends).</p><p>Consult this when displaying entity values, units, or state strings in cards to ensure consistent formatting and translation support.</p><hr><h2 id="home-assistant-services-implementation-notes" tabindex="-1">Home Assistant Services: Implementation Notes <a class="header-anchor" href="#home-assistant-services-implementation-notes" aria-label="Permalink to &quot;Home Assistant Services: Implementation Notes&quot;">​</a></h2><p><a href="./ha-services.html">Full reference →</a></p><p>Documents how the <code>lcards.*</code> actions are registered and validated, and the server-push channel (<code>lcards_event</code> over <code>lcards/subscribe</code>) that delivers alert modes, reloads, log levels, screen effects, sounds, portal overlays, Borg and astrometrics commands to connected browsers, with optional per-device and per-user targeting.</p><p>Consult this when tracing how a Home Assistant action reaches the browser, or when adding an action that needs the push channel.</p><hr><h2 id="shape-texture-system" tabindex="-1">Shape Texture System <a class="header-anchor" href="#shape-texture-system" aria-label="Permalink to &quot;Shape Texture System&quot;">​</a></h2><p><a href="./shape-texture-system.html">Full reference →</a></p><p>The <code>shape_texture</code> option: declarative effects (grid, plasma, fluid, level fills and more) drawn with Canvas2D on a <code>&lt;canvas&gt;</code> inside a <code>&lt;foreignObject&gt;</code> in the card SVG, clipped to the button or elbow shape and driven by one shared animation loop (<code>CanvasTextureRenderer</code>, <code>src/core/packs/textures/</code>). Colours and templates resolve through the same pipeline as the rest of the card.</p><p>Consult this when configuring animated textures on cards, adding a texture preset, or tracing texture colour resolution.</p><hr><h2 id="persistent-storage" tabindex="-1">Persistent Storage <a class="header-anchor" href="#persistent-storage" aria-label="Permalink to &quot;Persistent Storage&quot;">​</a></h2><p><a href="./storage.html">Full reference →</a></p><p>The integration&#39;s key/value store (Home Assistant&#39;s <code>Store</code>, written under <code>.storage/</code>), exposed over the <code>lcards/storage/*</code> WebSocket commands, with per-user and per-device namespaces. Values survive Home Assistant restarts. Its users are the scoped settings service (sound settings, theme overrides, connection overlay settings), the sound manager&#39;s custom schemes, device identity (registered devices), and the config panel&#39;s storage explorer and users and devices tabs. Layout edits are not stored here: the layout view saves through Home Assistant&#39;s own dashboard config (<code>lovelace.saveConfig</code>).</p><p>Consult this when implementing a setting that must survive page reloads and Home Assistant restarts.</p>',35)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
